    /// <summary>
    /// C# Wrapper-Methods for NPP functions defined in npp.h, nppversion.h, nppcore.h, nppi.h, npps.h, nppdefs.h
    /// </summary>
    public static class NPPNativeMethods
    {
        internal const string NPPC_API_DLL_NAME = "nppc64_13";
        internal const string NPPIAL_API_DLL_NAME = "nppial64_13";
        internal const string NPPICC_API_DLL_NAME = "nppicc64_13";
        internal const string NPPIDEI_API_DLL_NAME = "nppidei64_13";
        internal const string NPPIF_API_DLL_NAME = "nppif64_13";
        internal const string NPPIG_API_DLL_NAME = "nppig64_13";
        internal const string NPPIM_API_DLL_NAME = "nppim64_13";
        internal const string NPPIST_API_DLL_NAME = "nppist64_13";
        internal const string NPPISU_API_DLL_NAME = "nppisu64_13";
        internal const string NPPITC_API_DLL_NAME = "nppitc64_13";
        internal const string NPPS_API_DLL_NAME = "npps64_13";


#if (NETCOREAPP)
        internal const string NPPC_API_DLL_NAME_LINUX = "nppc";
        internal const string NPPIAL_API_DLL_NAME_LINUX = "nppial";
        internal const string NPPICC_API_DLL_NAME_LINUX = "nppicc";
        internal const string NPPIDEI_API_DLL_NAME_LINUX = "nppidei";
        internal const string NPPIF_API_DLL_NAME_LINUX = "nppif";
        internal const string NPPIG_API_DLL_NAME_LINUX = "nppig";
        internal const string NPPIM_API_DLL_NAME_LINUX = "nppim";
        internal const string NPPIST_API_DLL_NAME_LINUX = "nppist";
        internal const string NPPISU_API_DLL_NAME_LINUX = "nppisu";
        internal const string NPPITC_API_DLL_NAME_LINUX = "nppitc";
        internal const string NPPS_API_DLL_NAME_LINUX = "npps";
        internal const string NPP_SHORT_VERSION_LINUX = "13";
        internal const string NPP_LONG_VERSION_LINUX = "13.1.0.59";

        static NPPNativeMethods()
        {
            NativeLibrary.SetDllImportResolver(typeof(NPPNativeMethods).Assembly, ImportResolver);
        }

        private static IntPtr ImportResolver(string libraryName, System.Reflection.Assembly assembly, DllImportSearchPath? searchPath)
        {
            IntPtr libHandle = IntPtr.Zero;
            if (!RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
            {
                //On Windows, use the default library name
                return libHandle;
            }

            string libToLoad = null;
            switch (libraryName)
            {
                case NPPC_API_DLL_NAME:
                    libToLoad = NPPC_API_DLL_NAME_LINUX;
                    break;
                case NPPIAL_API_DLL_NAME:
                    libToLoad = NPPIAL_API_DLL_NAME_LINUX;
                    break;
                case NPPICC_API_DLL_NAME:
                    libToLoad = NPPICC_API_DLL_NAME_LINUX;
                    break;
                case NPPIDEI_API_DLL_NAME:
                    libToLoad = NPPIDEI_API_DLL_NAME_LINUX;
                    break;
                case NPPIF_API_DLL_NAME:
                    libToLoad = NPPIF_API_DLL_NAME_LINUX;
                    break;
                case NPPIG_API_DLL_NAME:
                    libToLoad = NPPIG_API_DLL_NAME_LINUX;
                    break;
                case NPPIM_API_DLL_NAME:
                    libToLoad = NPPIM_API_DLL_NAME_LINUX;
                    break;
                case NPPIST_API_DLL_NAME:
                    libToLoad = NPPIST_API_DLL_NAME_LINUX;
                    break;
                case NPPISU_API_DLL_NAME:
                    libToLoad = NPPISU_API_DLL_NAME_LINUX;
                    break;
                case NPPITC_API_DLL_NAME:
                    libToLoad = NPPITC_API_DLL_NAME_LINUX;
                    break;
                case NPPS_API_DLL_NAME:
                    libToLoad = NPPS_API_DLL_NAME_LINUX;
                    break;
                default:
                    return libHandle; //unknown lib to load
            }

            //first try the exact version:
            bool res = NativeLibrary.TryLoad("lib" + libToLoad + ".so." + NPP_LONG_VERSION_LINUX, assembly, DllImportSearchPath.SafeDirectories, out libHandle);
            if (res)
            {
                return libHandle;
            }

            //if no exact match found, try major version:
            res = NativeLibrary.TryLoad("lib" + libToLoad + ".so." + NPP_SHORT_VERSION_LINUX, assembly, DllImportSearchPath.SafeDirectories, out libHandle);
            if (res)
            {
                return libHandle;
            }

            //if still no match, try with only the lib name:
            res = NativeLibrary.TryLoad(libToLoad, assembly, DllImportSearchPath.SafeDirectories, out libHandle);
            if (!res)
            {
                Debug.WriteLine("Failed to load '" + libToLoad + "' shared library. Falling back to (Windows-) default library name '"
                    + libraryName + "'. Check LD_LIBRARY_PATH environment variable for correct paths.");
            }

            //On Windows, use the default library name
            return libHandle;
        }

        [MethodImpl(MethodImplOptions.NoOptimization)]
        internal static void Init()
        {
            //Need that to have the constructor called before any library call.
        }
#endif

        /// <summary>
        /// nppcore.h
        /// </summary>
        public static class NPPCore
        {
#if (NETCOREAPP)
            static NPPCore()
            {
                NPPNativeMethods.Init();
            }
#endif
            [DllImport(NPPC_API_DLL_NAME, EntryPoint = "nppGetLibVersion", CallingConvention = CallingConvention.Cdecl)]
            private static extern IntPtr nppGetLibVersionInternal();

            /// <summary>
            /// Get the NPP library version.
            /// </summary>
            /// <returns>A struct containing separate values for major and minor revision and build number.</returns>
            public static NppLibraryVersion nppGetLibVersion()
            {
                IntPtr ptr = nppGetLibVersionInternal();
                NPP.NppLibraryVersion version;
                version = (NPP.NppLibraryVersion)Marshal.PtrToStructure(ptr, typeof(NPP.NppLibraryVersion));
                return version;
            }
        }

