                /// Error codes:
                ///         - #NPP_SIZE_ERROR Indicates an error condition if any image dimension
                ///           has zero or negative value
                ///         - #NPP_RECT_ERROR Indicates an error condition if width or height of
                ///           the intersection of the srcRoi and source image is less than or
                ///           equal to 1
                ///         - #NPP_COEFF_ERROR Indicates an error condition if coefficient values
                ///           are invalid
                /// </returns>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiGetPerspectiveTransform(NppiRect srcRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 8)] double[,] quad, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 9)] double[,] coeffs);


                /// <summary>
