                ///           equal to 1
                ///         - #NPP_COEFF_ERROR Indicates an error condition if coefficient values
                ///           are invalid
                /// </returns>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiGetPerspectiveQuad(NppiRect srcRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 8)] double[,] quad, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 9)] double[,] coeffs);


                /// <summary>
