                ///           are invalid
                /// </returns>
                [DllImport(NPPIG_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiGetPerspectiveBound(NppiRect srcRoi, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 4)] double[,] bound, [In, MarshalAs(UnmanagedType.LPArray, SizeConst = 9)] double[,] coeffs);

            }


