            /// <summary>
            /// Filters the image using a separable Gaussian filter kernel with user supplied floating point coefficients with downsampling and border control.
            /// If the downsampling rate is equivalent to an integer value then unnecessary source pixels are just skipped.
            /// If any portion of the mask overlaps the source image boundary the requested border type operation is applied to all mask pixels
            /// which fall outside of the source image.
            /// Filters the image using a separable Gaussian filter kernel with user supplied floating point coefficients with upsampling and border control.
            /// If the upsampling rate is equivalent to an integer value then unnecessary source pixels are just skipped.
            /// If any portion of the mask overlaps the source image boundary the requested border type operation is applied to all mask pixels
            /// which fall outside of the source image.
            /// Currently only the <see cref="NppiBorderType.Replicate"/> and <see cref="NppiBorderType.Mirror"/> border type operation are supported.
            /// </summary>
            public class FilterGaussPyramid
            {
#if (NETCOREAPP)
                static FilterGaussPyramid()
                {
                    NPPNativeMethods.Init();
                }
#endif
                /// <summary>
                /// Calculate destination image SizeROI width and height from source image ROI width and height and downsampling rate.
                /// It is highly recommended that this function be use to determine the destination image ROI for consistent results.
                /// </summary>
                /// <param name="nSrcROIWidth">The desired source image ROI width, must be &lt;=  oSrcSize.width.</param>
                /// <param name="nSrcROIHeight">The desired source image ROI height, must be &lt;=  oSrcSize.height.</param>
                /// <param name="pDstSizeROI">Host memory pointer to the destination image roi_specification.</param>
                /// <param name="nRate">The downsampling rate to be used.  For integer equivalent rates unnecessary source pixels are just skipped. For non-integer rates the source image is bilinear interpolated. nRate must be > 1.0F and &lt;=  10.0F. </param>
                /// <returns>
                /// <see cref="NppStatus.StepError"/>, <see cref="NppStatus.NotEvenStepError"/>, <see cref="NppStatus.NullPointerError"/>, <see cref="NppStatus.AlignmentError"/>, <see cref="NppStatus.StepError"/>, <see cref="NppStatus.SizeError"/>
                /// </returns>
                [DllImport(NPPIF_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiGetFilterGaussPyramidLayerDownBorderDstROI(int nSrcROIWidth, int nSrcROIHeight, ref NppiSize pDstSizeROI, float nRate);



                /// <summary>
                /// Calculate destination image minimum and maximum SizeROI width and height from source image ROI width and height and upsampling rate. It is highly recommended that this function be use to determine the best destination image ROI for consistent results. 
                /// </summary>
                /// <param name="nSrcROIWidth">The desired source image ROI width, must be &lt;= oSrcSize.width.</param>
                /// <param name="nSrcROIHeight">The desired source image ROI height, must be &lt;= oSrcSize.height.</param>
                /// <param name="pDstSizeROIMin">Host memory pointer to the minimum recommended destination image roi_specification.</param>
                /// <param name="pDstSizeROIMax">Host memory pointer to the maximum recommended destination image roi_specification.</param>
                /// <param name="nRate">The upsampling rate to be used.  For integer equivalent rates unnecessary source pixels are just skipped. For non-integer rates the source image is bilinear interpolated. nRate must be > 1.0F and &lt;=  10.0F. </param>
                /// <returns>
                /// <see cref="NppStatus.StepError"/>, <see cref="NppStatus.NotEvenStepError"/>, <see cref="NppStatus.NullPointerError"/>, <see cref="NppStatus.AlignmentError"/>, <see cref="NppStatus.StepError"/>, <see cref="NppStatus.SizeError"/>
                /// </returns>
                [DllImport(NPPIF_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern NppStatus nppiGetFilterGaussPyramidLayerUpBorderDstROI(int nSrcROIWidth, int nSrcROIHeight, ref NppiSize pDstSizeROIMin, ref NppiSize pDstSizeROIMax, float nRate);

            }



