                /// <returns>
                /// A pointer to the new signal. 0 (NULL-pointer) indicates
                ///         that an error occurred during allocation.
                /// </returns>
                [DllImport(NPPS_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern CUdeviceptr nppsMalloc_16sc(SizeT nSize);


                /// <summary>
                /// 32-bit unsigned signal allocator.
                /// </summary>
                /// <param name="nSize">Number of unsigned ints in the new signal.</param>
                /// <returns>
                /// A pointer to the new signal. 0 (NULL-pointer) indicates
                ///         that an error occurred during allocation.
                /// </returns>
