                public static extern CUdeviceptr nppsMalloc_32u(SizeT nSize);


                /// <summary>
                /// 32-bit integer signal allocator.
                /// </summary>
                /// <param name="nSize">Number of ints in the new signal.</param>
                /// <returns>
                /// A pointer to the new signal. 0 (NULL-pointer) indicates
                ///         that an error occurred during allocation.
                /// </returns>
                [DllImport(NPPS_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern CUdeviceptr nppsMalloc_32s(SizeT nSize);


                /// <summary>
                /// 32-bit complex integer signal allocator.
                /// </summary>
                /// <param name="nSize">Number of complex integner values in the new signal.</param>
                /// <returns>
                /// A pointer to the new signal. 0 (NULL-pointer) indicates
                ///         that an error occurred during allocation.
                /// </returns>
                [DllImport(NPPS_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern CUdeviceptr nppsMalloc_32sc(SizeT nSize);


                /// <summary>
                /// 32-bit float signal allocator.
                /// </summary>
                /// <param name="nSize">Number of floats in the new signal.</param>
                /// <returns>
                /// A pointer to the new signal. 0 (NULL-pointer) indicates
                ///         that an error occurred during allocation.
                /// </returns>
                [DllImport(NPPS_API_DLL_NAME, CallingConvention = CallingConvention.Cdecl)]
                public static extern CUdeviceptr nppsMalloc_32f(SizeT nSize);


